package dev.otectus.mcakingdoms.interaction;

import dev.otectus.mcakingdoms.api.*;
import dev.otectus.mcakingdoms.api.factions.*;
import dev.otectus.mcakingdoms.factions.*;
import net.minecraft.resources.ResourceLocation;
import java.util.*;
import static dev.otectus.mcakingdoms.interaction.ActionRegistry.*;

public final class StandingTasks {
    private static final Constraint KINGDOM_DELTA=Constraint.range(-2000,2000,"points",25),LOCAL_DELTA=Constraint.range(-100,100,"points",5);
    /** Companion and optional mods whose installed version operators check; shared with the integrations command. */
    public static final List<String> INTEGRATIONS=List.of("mca","mcaquests","mcaconversations","mcareputation","mcacrime","townstead","recruits","dotcoinmod","runicskills","runic_gods","runic_races");
    private static KingdomsFactionsService service(Context c){return KingdomsFactionsApi.get(c.server());}
    private static void task(String id,String title,boolean change,List<Field> fields,Handler handler){add(new Task("standing."+id,"Administration",title,change?"Operator maintenance for kingdom reputation. Review the selected player and affected kingdom.":"Operator view of kingdom reputation records. Read-only.",true,change,fields,c->Long.toString(service(c).revision()),handler));}
    public static void init(){
        targets("standing_event",c->{if(!(service(c) instanceof FactionServiceImpl impl))return List.of();return impl.pendingMappings(c.player).stream().map(v->{String name="Player";try{name=BasicTargets.player(c,UUID.fromString(v.payload().get("player")));}catch(Exception ignored){}return new Choice(v.id().toString(),"Standing event "+v.sequence()+" · "+name,"Unmapped change: "+v.payload().getOrDefault("projectedDelta","unknown"),Map.of("revision",""+service(c).revision()));}).toList();});
        targets("mca_community",c->dev.otectus.mcakingdoms.compat.mca.McaCompat.operatorCommunities(c.player).stream().map(v->new Choice(v.reference().format(),v.label(),"Native community in "+v.reference().dimension())).toList());
        task("diagnostics","Inspect reputation synchronization",false,List.of(),c->List.of(tr("interaction.mcakingdoms.standing.mode","Mode: %s",ServerFacts.syncMode()),service(c) instanceof FactionServiceImpl impl?impl.diagnosticSummary():"Provider diagnostics unavailable."));
        for(boolean apply:new boolean[]{false,true})task(apply?"migration_apply":"migration_preview",apply?"Import reviewed legacy reputation":"Preview legacy reputation migration",apply,List.of(),c->{var before=service(c).previewLegacyMigration();if(apply&&!before.importable())throw new IllegalArgumentException("Resolve missing sources, mappings or conflicts before importing.");var r=apply?service(c).importLegacyMigration():before;var lines=new ArrayList<String>();lines.add("Source available: "+r.sourceAvailable()+"\nAlready imported: "+r.alreadyImported()+"\nInputs: "+r.inputCount()+"\nUnmapped: "+r.unmapped().size()+"\nReady to import: "+r.importable());r.entries().forEach(e->lines.add(BasicTargets.player(c,e.playerId())+" · "+e.kingdomId().getPath()+" · baseline "+e.baseline()+(e.conflict()?" · conflict with existing score "+e.existingScore():"")));r.unmapped().forEach(e->lines.add(BasicTargets.player(c,e.playerId())+" · "+e.community()+" · "+e.reason()));return lines;});
        task("get","Inspect a player's kingdom standing",false,List.of(pick("player","Player","player"),pick("kingdom","Kingdom","kingdom")),c->service(c).getStanding(c.uuid("player"),c.id("kingdom")).map(v->"Score: "+v.score()+"\nStanding tier: "+v.tierId()).orElse("No record: neutral standing."));
        task("add","Adjust kingdom standing",true,List.of(pick("player","Player","player"),pick("kingdom","Kingdom","kingdom"),number("delta","Standing change",0,KINGDOM_DELTA)),c->{int delta=c.integer("delta",KINGDOM_DELTA);var r=service(c).apply(new FactionStandingRequest(c.uuid("player"),c.id("kingdom"),delta,new ResourceLocation("mcakingdoms","faction_gui"),FactionChangeCause.ADMIN,UUID.randomUUID(),0,Optional.empty(),Optional.of("Reviewed administrative adjustment"),false));return "Applied change: "+r.appliedDelta()+"\nNew score: "+r.standing().score()+"\nStatus: "+words(r.status().name());});
        task("local_effect","Adjust native community standing",true,List.of(pick("player","Player","player"),pick("community","Native community","mca_community"),number("delta","Local change",0,LOCAL_DELTA)),c->{int delta=c.integer("delta",LOCAL_DELTA);return service(c).deliverLocalEffect(c.uuid("player"),McaCommunityRef.parse(c.text("community")).orElseThrow(),delta,UUID.randomUUID(),0,"Reviewed administrative local effect");});
        task("pending_map","Assign an unmapped standing event",true,List.of(pick("event","Pending event","standing_event"),pick("kingdom","Kingdom","kingdom")),c->{if(!(service(c) instanceof FactionServiceImpl impl))throw new IllegalArgumentException("Standing provider unavailable.");var r=impl.resolvePending(c.uuid("event"),c.id("kingdom")).orElseThrow(()->new IllegalArgumentException("Event is no longer awaiting a mapping."));return "Mapping resolved. Applied change: "+r.appliedDelta()+". Status: "+words(r.status().name());});
        add(new Task("administration.integrations","Administration","Check installed integrations","Lists the companion mods this server has installed, by version. Installed is not the same as usable: Server health shows which capabilities bound.",true,false,List.of(),c->"",c->{var lines=new ArrayList<Object>();for(String id:INTEGRATIONS)lines.add(id+": "+net.minecraftforge.fml.ModList.get().getModContainerById(id).map(m->"installed "+m.getModInfo().getVersion()).orElse("not installed"));lines.add("Civic services: "+dev.otectus.mcakingdoms.civic.CivicRuntime.get(c.server()).diagnostic());
            lines.add(tr("interaction.mcakingdoms.integrations.recruits","Recruits: the military bridge is gated to exactly Recruits 1.15.2; any other version runs with the integration off."));
            lines.add(tr("interaction.mcakingdoms.integrations.health","Installed is not the same as usable. Open Server health to see which capabilities bound and which features are switched on."));return lines;}));
    }
    private StandingTasks(){}
}
